#!/usr/bin/env python3
"""Embeds data/prelude.tt as a single shared .rodata array in namespace tt."""
import sys

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <input.tt> <output.h>", file=sys.stderr)
        sys.exit(1)
    in_path, out_path = sys.argv[1], sys.argv[2]
    with open(in_path, "rb") as f:
        data = f.read()

    lines = [
        "// Auto-generated by tools/embed_prelude.py from data/prelude.tt — DO NOT EDIT.",
        "#pragma once",
        "#include <cstddef>",
        "",
        "namespace tt {",
        f"extern const size_t kEmbeddedPreludeLen = {len(data)}u;",
        "extern const char kEmbeddedPrelude[] = {",
    ]
    for i in range(0, len(data), 16):
        chunk = data[i:i+16]
        hexes = ", ".join(f"0x{b:02x}" for b in chunk)
        lines.append(f"  {hexes},")
    lines.append("  0x00")
    lines.append("};")
    lines.append("}  // namespace tt")
    lines.append("")

    with open(out_path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

if __name__ == "__main__":
    main()
